def score(program: str) -> float:
    import ast
    try:
        tree = ast.parse(program)
        count = 0
        for node in ast.walk(tree):
            if isinstance(node, (ast.If, ast.For, ast.While)):
                count += 1
        return min(1.0, max(0.0, count / 15.0))
    except:
        return 0.5

