import ast, zlib
def score(program: str) -> float:
    try:
        t = ast.parse(program.strip())
    except Exception:
        return 0.01
    v = 0.0
    for n in ast.walk(t):
        v += 1 + zlib.crc32(type(n).__name__.encode()) % 89 / 89
    return v / (v + 60)

